oxy_webhelp_navlinks = {"aws_rds_recovery-d39536e19738":{"topics":[{"title":"Recovery options for Amazon RDS","shortdesc":"<p class=\"shortdesc\"><span class=\"ph\">RSC<\/span> provides two recovery options for Amazon RDS and Aurora         databases. Point-in-time export ensures recovery within the same region based on continuous         backups, while snapshot export supports recovery within the same region or across regions         using on-demand or scheduled snapshots.<\/p>","href":"saas\/aws_rds_recovery_options.html","attributes":{"data-id":"aws_rds_recovery_options"},"menu":{"hasChildren":false},"tocID":"aws_rds_recovery_options-d39536e19755","topics":[]},{"title":"Amazon RDS recovery considerations","shortdesc":"<p class=\"shortdesc\">Review the recovery behavior before recovering Amazon RDS and Aurora         databases.<\/p>","href":"saas\/aws_rds_recovery_considerations.html","attributes":{"data-id":"aws_rds_recovery_considerations"},"menu":{"hasChildren":false},"tocID":"aws_rds_recovery_considerations-d39536e19768","topics":[]},{"title":"Amazon RDS and Aurora PostgreSQL export and recovery engine options","shortdesc":"<p class=\"shortdesc\">Engine version availability varies by engine type and snapshot type when you export         or recover a snapshot. Selecting an unsupported version fails the export operation. Use this         reference to identify the supported target versions and to understand the error messages         that appear when an invalid version is chosen.<\/p>","href":"saas\/aws_rds_engine_version_selection.html","attributes":{"data-id":"aws_rds_engine_version_selection"},"menu":{"hasChildren":false},"tocID":"aws_rds_engine_version_selection-d39536e19779","topics":[]},{"title":"Archived snapshot to Amazon S3 recovery use cases","shortdesc":"<p class=\"shortdesc\">Understand when to use Export to S3, the output file layout written to your Amazon S3         bucket, and the bucket and encryption behavior to consider before you start.<\/p>","href":"saas\/aws_rds_recover_to_s3.html","attributes":{"data-id":"aws_rds_recover_to_s3"},"menu":{"hasChildren":false},"tocID":"aws_rds_recover_to_s3-d39536e19790","topics":[]},{"title":"Importing the recovered files into a PostgreSQL database","shortdesc":"<p class=\"shortdesc\"><span class=\"ph\">RSC<\/span> writes the dump files to your S3 bucket and you run the import         into a PostgreSQL server of your choice.<\/p>","href":"saas\/aws_rds_import_s3_postgresql.html","attributes":{"data-id":"aws_rds_import_s3_postgresql"},"menu":{"hasChildren":false},"tocID":"aws_rds_import_s3_postgresql-d39536e19801","topics":[]},{"title":"Exporting Amazon RDS snapshots","shortdesc":"<p class=\"shortdesc\">To create a point-in-time copy of an Amazon RDS database, export an Amazon RDS         on-demand, scheduled, or continuous snapshot. <span class=\"ph\">For RDS PostgreSQL, Aurora             PostgreSQL, RDS MySQL, Aurora MySQL, and RDS SQL Server databases, <span class=\"ph\">RSC<\/span> supports             exporting snapshots from primary and archived snapshots.<\/span><\/p>","href":"saas\/aws_rds_exporting_snapshots.html","attributes":{"data-id":"aws_rds_exporting_snapshots"},"menu":{"hasChildren":false},"tocID":"aws_rds_exporting_snapshots-d39536e19814","next":"aws_rds_exporting_snapshots-d39536e19814"}]}};